-- Modify "order_items" table
ALTER TABLE `order_items` MODIFY COLUMN `fulfillment_type` enum('auto','manual','upstream','reuse') NOT NULL, ADD COLUMN `delivery_source_id` bigint unsigned NULL, ADD INDEX `orderitem_delivery_source_id` (`delivery_source_id`);
-- Modify "products" table
ALTER TABLE `products` ADD COLUMN `category_protected` bool NOT NULL DEFAULT 0;
-- Create "product_delivery_sources" table
CREATE TABLE `product_delivery_sources` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `created_at` datetime(3) NOT NULL, `updated_at` datetime(3) NOT NULL, `subsite_id` bigint unsigned NOT NULL DEFAULT 0, `product_id` bigint unsigned NOT NULL, `sku_id` bigint unsigned NOT NULL DEFAULT 0, `purchase_key` varchar(64) NULL, `current_key` varchar(100) NULL, `status` varchar(20) NOT NULL DEFAULT "empty", `content` blob NULL, `connection_id` bigint unsigned NOT NULL DEFAULT 0, `upstream_product` varchar(128) NOT NULL DEFAULT "", `upstream_sku` varchar(128) NOT NULL DEFAULT "", `upstream_order_id` varchar(128) NOT NULL DEFAULT "", `connection_revision` varchar(64) NOT NULL DEFAULT "", `origin_procurement_id` bigint unsigned NOT NULL DEFAULT 0, `expires_at` bigint NOT NULL DEFAULT 0, `delivered_count` bigint NOT NULL DEFAULT 0, `max_deliveries` bigint NOT NULL DEFAULT 0, `submitted_at` bigint NOT NULL DEFAULT 0, `next_check_at` bigint NOT NULL DEFAULT 0, `exchange_rate` double NOT NULL DEFAULT 1, `cost_cents` bigint NOT NULL DEFAULT 0, `last_error` varchar(255) NOT NULL DEFAULT "", PRIMARY KEY (`id`), UNIQUE INDEX `productdeliverysource_current_key` (`current_key`), INDEX `productdeliverysource_status_next_check_at` (`status`, `next_check_at`), INDEX `productdeliverysource_subsite_id_product_id_sku_id` (`subsite_id`, `product_id`, `sku_id`), UNIQUE INDEX `purchase_key` (`purchase_key`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
